import{_ as r,a as t}from"./chunks/a0512a071a6cb4242311.BtYorL_r.js";import{_ as i,C as l,o,c as s,j as e,a as n,E as u,a5 as h}from"./chunks/framework.DNkHA0lr.js";const v=JSON.parse('{"title":"如果你很聪明，你的脑袋里正困着10万美元","description":"","frontmatter":{"title":"如果你很聪明，你的脑袋里正困着10万美元","originalTitle":"If You Are Smart, You Have $100,000 Trapped In Your Head","date":"2024-03-29","originalUrl":"https://thedankoe.com/letters/if-you-are-smart-you-have-100000-trapped-in-your-head/","minutes":9,"sourceHash":"d2662fc3931c7347a31ec1120b74b9f491cf5fbc05bce1c230485278c3d40534","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/if-you-are-smart-you-have-100000-trapped-in-your-head/"}]]},"headers":[],"relativePath":"letters/if-you-are-smart-you-have-100000-trapped-in-your-head.md","filePath":"letters/if-you-are-smart-you-have-100000-trapped-in-your-head.md"}'),d={name:"letters/if-you-are-smart-you-have-100000-trapped-in-your-head.md"};function c(f,p,m,_,b,y){const a=l("ArticleMeta");return o(),s("div",null,[p[0]||(p[0]=e("h1",{id:"如果你很聪明-你的脑袋里正困着10万美元",tabindex:"-1"},[n("如果你很聪明，你的脑袋里正困着10万美元 "),e("a",{class:"header-anchor",href:"#如果你很聪明-你的脑袋里正困着10万美元","aria-label":'Permalink to "如果你很聪明，你的脑袋里正困着10万美元"'},"​")],-1)),u(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/44HCE6auAa4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>控制你收入的唯一方式，也就是控制你人生的唯一方式，就是创造一个产品。</p><p>从你出生的那一天起，你就被教导要上学、找工作、存钱，直到你能退休，最终去做你想做的事。</p><p>你被训练成服从权威。学习你不关心的东西，为的是给你不关心的人工作，好让你最终能过上你关心的生活……只要对社会稍作观察，就知道这一天几乎永远不会到来。</p><p>你没有意识到，自己被编程成了社会中的一行代码，去为别人销售产品。</p><p>你的一生都用来构建别人的梦想，却不是你自己的。</p><p>好消息是，时代在变化。</p><p>工作的去中心化已经开始了。</p><p>现在的机会比以往任何时候都多。</p><p>远程工作已经成为常态。</p><p>自由职业者的比例自2020年以来，已从劳动力总数的36%增长到46.6%。</p><p>创作者经济预计将在2028年前从2500亿美元翻倍增长到4800亿美元。</p><p>多亏了互联网，权力正在重新回到个体手中。</p><p>我很早就意识到这一点。</p><p>我上高中的时候，YouTube才刚刚起势。</p><p>我注意到大多数人都在围绕自己的技能和热情创作内容。他们把自己一路学到的东西教给别人，而他们的个性让他们独一无二。</p><p>这促使我竭尽全力去做同样的事。</p><p>我开设了YouTube频道，尝试过dropshipping（代发货）、自由职业和代理业务等各种商业模式。</p><p>学会写代码并在一家网页设计公司找到工作后，我退学了。凭借在那里学到的东西，我开了自己的公司。</p><p>但有个问题。我想要的是自由。我很快意识到，客户项目其实和朝九晚五的工作差不多。</p><p>我在为我不关心的人做我不关心的自由职业项目。</p><p>这让我走向了社交媒体和Twitter。</p><p>从那时到现在，我已经摆脱了客户业务，平均每天工作2到4小时，去年作为一个个人品牌赚了410万美元的营收，利润率高得离谱。</p><h2 id="数字杠杆" tabindex="-1">数字杠杆 <a class="header-anchor" href="#数字杠杆" aria-label="Permalink to &quot;数字杠杆&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>社交媒体已经为任何人创造条件，让他们去做自己热爱的事。</p><p>唯一不相信这一点的人，是纯粹的消费者。那些无脑刷屏、给自己生活制造更多问题的人，还有那些囤积信息却从不付诸行动的人。</p><p>每个人既是创作者，也是消费者。</p><p>你给朋友发短信。你进行对话。你有想法。你每天都在创造。</p><p>你购买产品。你消费内容（就像我们自报纸和广播时代以来一直在做的那样）。你每天都在消费。</p><p>你必须消费才能创造，但如果你不去把握平衡，你的大脑就会变成一团压力和焦虑的乱麻，蒙蔽你看不清自己的潜力。</p><p>目前，注意力就在社交媒体上。这可能会变化，但原则始终不变：</p><p>如果你想掌控自己的人生，就必须在注意力所在的地方创造并分发有价值的产品。你必须为人类贡献的比你索取的更多。目前，这个地方就是社交媒体，认为自己不该参与这场新游戏的竞争，是愚蠢的。</p><p>美妙之处在于：</p><ul><li>你不需要启动资金</li><li>你不需要很多经验</li><li>你不需要很多粉丝</li><li>你不需要担心市场饱和</li><li>你不必为利润率、运营成本或供应链而神经质地焦虑</li></ul><p>科技已经发展到这样一个地步：你可以经营一个一人企业，利润率超过90%，每天只需工作2到4个小时。</p><p>这就是我创建<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>的原因。</p><h2 id="建立分发渠道" tabindex="-1">建立分发渠道 <a class="header-anchor" href="#建立分发渠道" aria-label="Permalink to &quot;建立分发渠道&quot;">​</a></h2><p>你需要受众。</p><p>现在，受众就在社交媒体上。</p><p>大多数人把社交媒体看作手机上一个无关紧要的应用，然而他们却把生命中的大部分时间花在上面。</p><p>你至今还没有意识到，它已经是经济、商业、学习乃至整个生活的重要组成部分。</p><p>我们的祖先在部落中为自己所扮演的角色拥有小规模的受众。</p><p>随着世界通过印刷机、广播和电视不断进步，我们为自己的工作获取受众的方式发生了巨大的变化。</p><p>重点是这样的：</p><p>你需要一群知道你做什么、以及这如何帮助他们的人。这正是你所工作的那家公司在做的事。这是成为你自己人生CEO的唯一途径。</p><p>你不需要挨家挨户地敲门。你不需要发出成千上万封陌生开发邮件。但你仍然需要为你的作品建立分发渠道。</p><p>现在，你可以把你的文章发在像X这样的应用上，让一个更大的账号转发你的作品，一天之内就能获得数百个粉丝。</p><p>大多数人认为自己无法建立受众，因为他们没有花时间去学习写作和说服这两项主权技能。</p><p>他们认为自己做不到：</p><ul><li>通过模仿那些行之有效的内容来写出有影响力的帖子（我们都是从模仿者起步的，不然还能怎么学？）</li><li>给一个大账号发私信，提供某种形式的价值（知识或金钱）以建立关系。</li><li>说服他们用那份价值换取你想要的东西（在社交媒体上转发一下）。</li><li>或者，写一篇关于某人的帖子，希望他们转发，因为这能给他们的社会证明添砖加瓦（<a href="https://x.com/hosun_chung/status/1772277469648720274" target="_blank" rel="noreferrer">前几天的例子</a>，他让别人转发了这篇文章，我上次查看时，这给他带来了将近700个粉丝。）</li><li>让成千上万的人看到你的帖子，其中不少人会关注你。</li><li>持续这个过程，直到你拥有一群求着要付钱给你的受众。</li><li>推出一个产品，获得你的自由。</li></ul><p>随着你不断练习这些技能，看到成果所需的时间会不断缩短。</p><p>一开始会很难，万事开头难，但你投入的时间会逐渐减少到每天1到2小时的<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">写作和自我推广</a>。</p><p>大多数人被困在奴隶式的教育里，学习一种特定职业技能，一辈子执行一串特定的任务。</p><p>他们变得依附于那项技能，拒绝学习任何能提升自身潜力的东西。</p><p>别成为那样的人。</p><p>如果你想掌控自己的未来，你必须用写作和说服这两项技能建立受众——自从我们在石头上刻下符号那天起，它们就一直是自由人的工具箱里的东西。</p><h2 id="打造产品" tabindex="-1">打造产品 <a class="header-anchor" href="#打造产品" aria-label="Permalink to &quot;打造产品&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>你可以做一个自由职业者。</p><p>你可以做一个教练。</p><p>你可以开一家代理公司。</p><p>但你仍然无法实现你开始创业时设定的那个大目标：</p><p>对自己时间的完全掌控。</p><p>这就是服务型业务的陷阱。它们作为起点可能是有用的，但我最近改变了想法。</p><p>过去，我建议人们先开一家服务型业务，在建立受众的过程中逐步转向产品。</p><p>许多人凭这个方法成功了，但失败的更多。</p><p>他们接受了一个错误的观念，认为只需花几个小时学一项技能，就能靠给客户交出糟糕的结果来骗取收入，取代自己原来的收入。</p><p>当然，如果你脑子清楚，开一家服务型业务赚点钱也没问题。</p><p>如果你还完全没有自我提升过，你最好玩长线游戏。</p><ul><li>提升自己</li><li>公开记录你的历程</li><li>把你的进步转化为一个产品</li><li>帮助别人实现你曾实现过的目标</li></ul><p>对于想要完全掌控自己时间的人来说，产品是杠杆最高的玩法。产品自我运转，在你睡觉的时候也能卖出去。</p><p>这就是为什么我们要从建立受众开始。</p><ul><li>你保持长线思维</li><li>你出于正确的理由在做这件事</li><li>你为自己打下了数十年成功的基础</li><li>你用一个产品帮助更多人取得成果</li><li>你的内容不会感觉被困在狭窄的框架里</li><li>你写内容是为了发现受众想要什么（根据互动情况判断）</li><li>你把这些当作火力，让你的产品获得成功</li></ul><p>你的脑袋里困着10万美元。</p><p>你要如何把它提取出来？</p><p>首先，要理解人们为什么会购买一个产品。</p><p>他们想看到一种转变。他们想看到自己生活中某个方面出现细微或剧烈的改善。</p><p>他们想通过掌握技能、提高生产力和自我提升来增加自己的市场价值。</p><p>他们想赚更多的钱，腾出更多的时间，提高生活质量。</p><p>所以，我们从那些永恒的市场开始。健康、财富、关系和幸福。</p><p>这就是我们定位任何要销售的产品的方式。</p><p>现在，按照这些步骤来：</p><ul><li>把自己变成你的用户画像</li><li>列出你的兴趣</li><li>列出你的目标</li><li>列出你的问题</li><li>列出克服这个问题、实现这个目标的确切方法</li></ul><p>现在你就有了一个品牌信息、几十个内容点子，以及一个盈利产品的起点。</p><p>至于潜在的想法，可以是与营养、训练、心理健康、灵性、技能习得、生产力、心理学，或者任何你在生活中能学到并从中受益的事物相关的一切。</p><p>如果你人生中还没取得太多成就，那这就是第一步。</p><p>是的，你得从你妈妈家的地下室里走出来，去培养某种形式的价值。真是令人震惊。</p><p>如果你已经在生活中实现过某个目标，那你就万事俱备了。把实现那个目标所需的一切都打包成一个数字产品。</p><p>一门课程、一次教练指导、一个训练营、一场工作坊、一个模板、一份清单、一套系统、一个教程、一个项目、一个追踪工具，或者任何你见过其他品牌或创作者卖过的东西。</p><p>你可以卖实体产品或服务，但在我看来，每个人的终极目标都应该是卖一个高利润的数字产品，它维护成本低，在你睡觉时也能自行销售。毕竟我们要的是自由，但要做到这一点，你需要有受众。</p><p>如果它已经在卖了，很好。别以为每个人都知道它。用你能找到的最独特的品牌——也就是你自己——去卖它，成为第一个向人们介绍这个产品重要性的人。它会卖出去的。</p><p>为了吸引受众，去给过去的自己、现在的自己和未来的自己写作。</p><p>打造一个你以前用过、但现在更好的产品。打造一个你想要却不存在的产品。打造一个能解决你生活中某个问题的产品。</p><p>通过展现这个产品如何影响了你的生活来推广它。个人经历是把你和其他所有人区别开来的东西。没有人能复制它。</p><p>我们在<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>中通过模板、任务和个人指导来教授这个进阶过程。</p><p>大多数企业失败，是因为他们试图解决一个自己从未亲身经历过的问题。别成为其中之一。</p><h2 id="先模仿-再创新" tabindex="-1">先模仿，再创新 <a class="header-anchor" href="#先模仿-再创新" aria-label="Permalink to &quot;先模仿，再创新&quot;">​</a></h2><p>你是个模仿者。</p><p>你脑子里的每一个想法，都是通过观察或学习外部事物而来的。</p><p>你通过自我反思所获得的那些发现，也只有借助这一点才有可能实现。</p><p>认为你不该模仿别人，尤其是当他们正在做的事情行之有效时，这种想法相当愚蠢。</p><p>模仿是我们生存的方式。</p><p>每个人既是模仿者，也是创新者。</p><p>创新者创造并测试新的想法。</p><p>模仿者把这些想法带到现实中，并把它们传播到全人类。</p><p>显然，你不能只是照抄别人做过的东西。那样你会变成一个被排斥的人。用你的大脑，长远思考一下。</p><p>如果你不知道该写什么或创作什么，你就必须沉浸在别人的写作或创作之中。</p><p>最好是大量的来源，直到你的大脑被压得几乎要爆炸。</p><p>这就是创造力的本质。张力的释放，最终带来突破。</p><p>建立一个你喜欢的写作素材库。</p><p>基于有效的东西练习写作，但要融入你自己的想法。</p><p>购买与你想创建的类似的数字产品。研究它们的结构，填补你自己产品中的空白。</p><p>当我创建一个教授网页设计技能的数字产品时，我已经懂得不少，所以我先列了产品大纲。</p><p>但我还是得购买其他课程，找出我自己的产品里缺了哪些部分。只有这样，我才能完成这个产品，并确保它足够体面。</p><p>剩下的都来自迭代。</p><p>你必须先发布一些很烂的文章和产品。</p><p>你必须看起来像个白痴。</p><p>你必须得到反馈，看看你的创作到底有没有价值。只有这样你才能改进，因为否则你根本无从知道该怎么改进。</p><p>写作，是为了建立受众。</p><p>发布产品，是为了赢得你的自由。</p><p>享受你接下来的一天吧。</p><p>Dan</p><hr><p><a href="/en/letters/if-you-are-smart-you-have-100000-trapped-in-your-head">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',125))])}const T=i(d,[["render",c]]);export{v as __pageData,T as default};
